// Frozen supplemental fixture for catalog entry text.regex-log-scan.v1.
// The catalog itself remains byte-for-byte frozen; this file freezes the generated bytes.

export const WORKLOAD_ID = "text.regex-log-scan.v1";
export const FIXTURE_SEED = 0x5a17c0de;
export const CORPUS_BYTES = 100 * 1024 * 1024;
export const RECORD_BYTES = 256;
export const RECORD_COUNT = CORPUS_BYTES / RECORD_BYTES;
export const EVENT_INTERVAL = 10;
export const EXPECTED_MATCHES = RECORD_COUNT / EVENT_INTERVAL;
export const EXPECTED_MATCHES_PER_PATTERN = EXPECTED_MATCHES / 20;

export const SAFE_PATTERNS = Object.freeze([
  { id: 0, category: "url", source: "http://%URL_TAIL%", prefix: "http://", matcher: "url-tail" },
  { id: 1, category: "url", source: "https://%URL_TAIL%", prefix: "https://", matcher: "url-tail" },
  { id: 2, category: "url", source: "ws://%URL_TAIL%", prefix: "ws://", matcher: "url-tail" },
  { id: 3, category: "url", source: "wss://%URL_TAIL%", prefix: "wss://", matcher: "url-tail" },
  { id: 4, category: "url", source: "ftp://%URL_TAIL%", prefix: "ftp://", matcher: "url-tail" },
  { id: 5, category: "url", source: "asset://%URL_TAIL%", prefix: "asset://", matcher: "url-tail" },
  { id: 6, category: "url", source: "api://%URL_TAIL%", prefix: "api://", matcher: "url-tail" },
  { id: 7, category: "url", source: "cdn://%URL_TAIL%", prefix: "cdn://", matcher: "url-tail" },
  { id: 8, category: "ip", source: "ip=%IPV4%", prefix: "ip=", matcher: "ipv4" },
  { id: 9, category: "ip", source: "client-ip:%IPV4%", prefix: "client-ip:", matcher: "ipv4" },
  { id: 10, category: "ip", source: "source-ip:%IPV4%", prefix: "source-ip:", matcher: "ipv4" },
  { id: 11, category: "ip", source: "dest-ip:%IPV4%", prefix: "dest-ip:", matcher: "ipv4" },
  { id: 12, category: "ip", source: "peer-ip:%IPV4%", prefix: "peer-ip:", matcher: "ipv4" },
  { id: 13, category: "ip", source: "origin-ip:%IPV4%", prefix: "origin-ip:", matcher: "ipv4" },
  { id: 14, category: "status", source: "status=%STATUS%", prefix: "status=", matcher: "status" },
  { id: 15, category: "status", source: "code=%STATUS%", prefix: "code=", matcher: "status" },
  {
    id: 16,
    category: "status",
    source: "http-status:%STATUS%",
    prefix: "http-status:",
    matcher: "status",
  },
  {
    id: 17,
    category: "status",
    source: "response-status:%STATUS%",
    prefix: "response-status:",
    matcher: "status",
  },
  {
    id: 18,
    category: "status",
    source: "result-status:%STATUS%",
    prefix: "result-status:",
    matcher: "status",
  },
  {
    id: 19,
    category: "status",
    source: "status-code:%STATUS%",
    prefix: "status-code:",
    matcher: "status",
  },
]);

const encoder = new TextEncoder();
const filler = encoder.encode("日志 café 東京 🚀 запись record ");

function xorshift32(value) {
  value ^= value << 13;
  value ^= value >>> 17;
  value ^= value << 5;
  return value >>> 0;
}

function tokenFor(pattern, eventIndex) {
  const value = xorshift32(
    (FIXTURE_SEED ^ eventIndex ^ Math.imul(pattern.id + 1, 0x9e3779b1)) >>> 0,
  );
  if (pattern.matcher === "url-tail") {
    return `${pattern.prefix}node-${
      value.toString(16).padStart(8, "0")
    }.example.test/path/${eventIndex}`;
  }
  if (pattern.matcher === "ipv4") {
    const a = 1 + (value & 0xfe);
    const b = (value >>> 8) & 0xff;
    const c = (value >>> 16) & 0xff;
    const d = (value >>> 24) & 0xff;
    return `${pattern.prefix}${a}.${b}.${c}.${d}`;
  }
  return `${pattern.prefix}${100 + (value % 500)}`;
}

export function generateCorpus(sizeBytes = CORPUS_BYTES) {
  if (sizeBytes % RECORD_BYTES !== 0) throw new Error("fixture size must be record-aligned");
  const bytes = new Uint8Array(sizeBytes);
  bytes.fill(0x20);
  const records = sizeBytes / RECORD_BYTES;
  for (let record = 0; record < records; record++) {
    const offset = record * RECORD_BYTES;
    bytes.set(filler, offset);
    const label = encoder.encode(String(record).padStart(6, "0"));
    bytes.set(label, offset + filler.byteLength);
    if (record % EVENT_INTERVAL === 0) {
      const eventIndex = record / EVENT_INTERVAL;
      const pattern = SAFE_PATTERNS[eventIndex % SAFE_PATTERNS.length];
      const token = encoder.encode(tokenFor(pattern, eventIndex));
      const tokenOffset = offset + 64;
      if (token.byteLength > RECORD_BYTES - 66) throw new Error("generated token exceeds record");
      bytes.set(token, tokenOffset);
    }
    bytes[offset + RECORD_BYTES - 1] = 0x0a;
  }
  return bytes;
}

export function makeAdversarialCorpus(lines) {
  return encoder.encode(`${lines.join("\n")}\n`);
}
